import "server-only";
import { initializeApp, getApps, getApp, cert } from "firebase-admin/app";
import { getAuth } from "firebase-admin/auth";
import { getFirestore } from "firebase-admin/firestore";
import { getStorage } from "firebase-admin/storage";
import { getMessaging } from "firebase-admin/messaging";

if (!process.env.FIREBASE_ADMIN_PROJECT_ID) {
  throw new Error("FIREBASE_ADMIN_PROJECT_ID is missing from .env.local");
}
if (!process.env.FIREBASE_ADMIN_CLIENT_EMAIL) {
  throw new Error("FIREBASE_ADMIN_CLIENT_EMAIL is missing from .env.local");
}
if (!process.env.FIREBASE_ADMIN_PRIVATE_KEY) {
  throw new Error("FIREBASE_ADMIN_PRIVATE_KEY is missing from .env.local");
}

const adminApp = getApps().length
  ? getApp()
  : initializeApp({
      credential: cert({
        projectId: process.env.FIREBASE_ADMIN_PROJECT_ID,
        clientEmail: process.env.FIREBASE_ADMIN_CLIENT_EMAIL,
        // Env vars flatten newlines — restore PEM format required by the cert.
        privateKey: process.env.FIREBASE_ADMIN_PRIVATE_KEY.replace(/\\n/g, "\n"),
      }),
    });

export const adminAuth = getAuth(adminApp);
export const adminDb = getFirestore(adminApp);
export const adminStorage = getStorage(adminApp);
export const adminMessaging = getMessaging(adminApp);
export { adminApp };

