"use client";

import {
  signInWithEmailAndPassword,
  signInWithPopup,
  signOut,
  onAuthStateChanged,
  GoogleAuthProvider,
  GithubAuthProvider,
  getIdToken,
  type User,
} from "firebase/auth";
import { auth } from "./client";

async function exchangeTokenForSession(user: User): Promise<void> {
  const idToken = await getIdToken(user);
  const res = await fetch("/api/auth/session", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ idToken }),
  });
  if (!res.ok) throw new Error("Failed to create session. Please try again.");
}

export async function signInWithEmail(email: string, password: string): Promise<User> {
  const { user } = await signInWithEmailAndPassword(auth, email, password);
  await exchangeTokenForSession(user);
  return user;
}

export async function signInWithGoogle(): Promise<User> {
  const { user } = await signInWithPopup(auth, new GoogleAuthProvider());
  await exchangeTokenForSession(user);
  return user;
}

export async function signInWithGitHub(): Promise<User> {
  const { user } = await signInWithPopup(auth, new GithubAuthProvider());
  await exchangeTokenForSession(user);
  return user;
}

export async function signOutUser(): Promise<void> {
  await signOut(auth);
  await fetch("/api/auth/session", { method: "DELETE" });
}

export function onAuthChange(callback: (user: User | null) => void): () => void {
  return onAuthStateChanged(auth, callback);
}

