import "server-only";
import { adminAuth } from "./admin";
import type { DecodedIdToken } from "firebase-admin/auth";

export const SESSION_COOKIE_NAME = "__session";
export const SESSION_EXPIRES_MS = 14 * 24 * 60 * 60 * 1000;
// Reject ID tokens older than this when minting a session cookie — prevents
// long-lived stolen ID tokens from being upgraded to long-lived sessions.
const MAX_ID_TOKEN_AGE_SECONDS = 5 * 60;

export class StaleIdTokenError extends Error {
  constructor() {
    super("ID token is too old; user must sign in again recently.");
    this.name = "StaleIdTokenError";
  }
}

/**
 * Mints a session cookie from a Firebase ID token.
 * Verifies the ID token first and rejects ones older than 5 minutes —
 * see https://firebase.google.com/docs/auth/admin/manage-cookies#sign_in
 */
export async function createSessionCookie(idToken: string): Promise<string> {
  const decoded = await adminAuth.verifyIdToken(idToken, true);
  if (Date.now() / 1000 - decoded.auth_time > MAX_ID_TOKEN_AGE_SECONDS) {
    throw new StaleIdTokenError();
  }
  return adminAuth.createSessionCookie(idToken, {
    expiresIn: SESSION_EXPIRES_MS,
  });
}

export async function verifySessionCookie(
  cookie: string,
): Promise<DecodedIdToken | null> {
  try {
    return await adminAuth.verifySessionCookie(cookie, true);
  } catch {
    return null;
  }
}

/**
 * Revokes all refresh tokens for the user identified by the cookie, then
 * returns the decoded token. Call before clearing the cookie on sign-out so
 * a leaked cookie can't continue to be used.
 */
export async function revokeSession(cookie: string): Promise<void> {
  const decoded = await verifySessionCookie(cookie);
  if (decoded) {
    await adminAuth.revokeRefreshTokens(decoded.sub);
  }
}

