import { cookies } from "next/headers";
import {
  createSessionCookie,
  revokeSession,
  SESSION_COOKIE_NAME,
  SESSION_EXPIRES_MS,
  StaleIdTokenError,
} from "@/infra/firebase/auth-server";

// Fail closed: cookies are `secure` unless we're explicitly in development.
// `NODE_ENV === "production"` is wrong because staging/preview deployments
// often have NODE_ENV unset and would otherwise send cookies over HTTP.
const SECURE_COOKIE = process.env.NODE_ENV !== "development";

export async function POST(req: Request) {
  let idToken: string | undefined;
  try {
    const body = (await req.json()) as { idToken?: unknown };
    if (typeof body.idToken === "string") idToken = body.idToken;
  } catch {
    return new Response("Bad request", { status: 400 });
  }

  if (!idToken) {
    return new Response("idToken is required", { status: 400 });
  }

  let sessionCookie: string;
  try {
    sessionCookie = await createSessionCookie(idToken);
  } catch (err: unknown) {
    if (err instanceof StaleIdTokenError) {
      return new Response("Recent sign-in required", { status: 401 });
    }
    return new Response("Unauthorized", { status: 401 });
  }

  const cookieStore = await cookies();
  cookieStore.set(SESSION_COOKIE_NAME, sessionCookie, {
    httpOnly: true,
    secure: SECURE_COOKIE,
    sameSite: "lax",
    path: "/",
    maxAge: SESSION_EXPIRES_MS / 1000,
  });

  return new Response("OK", { status: 200 });
}

export async function DELETE() {
  const cookieStore = await cookies();
  const existing = cookieStore.get(SESSION_COOKIE_NAME)?.value;

  // Revoke server-side BEFORE clearing the cookie. Without this, a copy of
  // the cookie (e.g. exfiltrated via XSS) keeps working for 14 days even
  // after the user "signs out."
  if (existing) {
    try {
      await revokeSession(existing);
    } catch {
      // Best-effort — still clear the local cookie even if revocation fails.
    }
  }

  cookieStore.set(SESSION_COOKIE_NAME, "", {
    httpOnly: true,
    secure: SECURE_COOKIE,
    sameSite: "lax",
    path: "/",
    maxAge: 0,
  });
  return new Response("OK", { status: 200 });
}

