export const runtime = "nodejs";

import { NextResponse } from "next/server";
import type { NextRequest } from "next/server";
import {
  verifySessionCookie,
  SESSION_COOKIE_NAME,
} from "@/infra/firebase/auth-server";

const PUBLIC_PATHS = ["/sign-in", "/sign-up", "/api/auth"];

// Exact match or path-boundary prefix. `startsWith` alone matches "/sign-in-evil",
// which would let an attacker register a route and bypass auth.
function isPublic(pathname: string): boolean {
  return PUBLIC_PATHS.some(
    (p) => pathname === p || pathname.startsWith(p + "/"),
  );
}

export async function middleware(request: NextRequest) {
  const { pathname } = request.nextUrl;
  if (isPublic(pathname)) {
    return NextResponse.next();
  }

  const cookie = request.cookies.get(SESSION_COOKIE_NAME)?.value;
  if (!cookie) {
    return NextResponse.redirect(new URL("/sign-in", request.url));
  }

  const decoded = await verifySessionCookie(cookie);
  if (!decoded) {
    return NextResponse.redirect(new URL("/sign-in", request.url));
  }

  return NextResponse.next();
}

export const config = {
  matcher: ["/((?!_next/static|_next/image|favicon.ico).*)"],
};

