import { adminDb } from "./admin";
import type { DocumentData, WhereFilterOp } from "firebase-admin/firestore";

export async function getDocument<T extends DocumentData>(
  collectionPath: string,
  id: string,
): Promise<(T & { id: string }) | null> {
  const snap = await adminDb.collection(collectionPath).doc(id).get();
  if (!snap.exists) return null;
  return { id: snap.id, ...(snap.data() as T) };
}

export async function setDocument<T extends DocumentData>(
  collectionPath: string,
  id: string,
  data: T,
): Promise<void> {
  await adminDb.collection(collectionPath).doc(id).set(data);
}

export async function updateDocument(
  collectionPath: string,
  id: string,
  data: Partial<DocumentData>,
): Promise<void> {
  await adminDb.collection(collectionPath).doc(id).update(data);
}

export async function deleteDocument(collectionPath: string, id: string): Promise<void> {
  await adminDb.collection(collectionPath).doc(id).delete();
}

export async function queryDocuments<T extends DocumentData>(
  collectionPath: string,
  field: string,
  operator: WhereFilterOp,
  value: unknown,
): Promise<(T & { id: string })[]> {
  const snap = await adminDb
    .collection(collectionPath)
    .where(field, operator, value)
    .get();
  return snap.docs.map((d) => ({ id: d.id, ...(d.data() as T) }));
}

