import "server-only";
import { adminStorage } from "./admin";

const DEFAULT_BUCKET = process.env.NEXT_PUBLIC_FIREBASE_STORAGE_BUCKET ?? "";

/**
 * Rejects file paths that could escape the intended directory or contain
 * null bytes. Callers passing user-controlled input should still scope paths
 * with a user-id prefix on top of this check.
 */
function assertSafeFilePath(filePath: string): void {
  if (!filePath || filePath.length === 0) {
    throw new Error("filePath is required.");
  }
  if (filePath.includes("\0")) {
    throw new Error("filePath contains a null byte.");
  }
  if (filePath.startsWith("/")) {
    throw new Error("filePath must not start with '/'.");
  }
  // Block parent-directory traversal segments.
  const segments = filePath.split("/");
  if (segments.some((s) => s === ".." || s === ".")) {
    throw new Error("filePath must not contain '.' or '..' segments.");
  }
}

export async function getSignedUploadUrl(
  filePath: string,
  contentType: string,
  expiresInMs = 15 * 60 * 1000,
): Promise<string> {
  assertSafeFilePath(filePath);
  const [url] = await adminStorage
    .bucket(DEFAULT_BUCKET)
    .file(filePath)
    .getSignedUrl({
      action: "write",
      expires: Date.now() + expiresInMs,
      contentType,
    });
  return url;
}

export async function getSignedDownloadUrl(
  filePath: string,
  expiresInMs = 60 * 60 * 1000,
): Promise<string> {
  assertSafeFilePath(filePath);
  const [url] = await adminStorage
    .bucket(DEFAULT_BUCKET)
    .file(filePath)
    .getSignedUrl({
      action: "read",
      expires: Date.now() + expiresInMs,
    });
  return url;
}

export async function deleteFile(filePath: string): Promise<void> {
  assertSafeFilePath(filePath);
  await adminStorage.bucket(DEFAULT_BUCKET).file(filePath).delete();
}

